/* 独立HTML行模板，异步聚合接口提供全部工作台数据。 */
Eam.registerInit(async function(){
 const ui=EamUiComponents,$=id=>document.getElementById(id);let data,page=1,ticket=0;
 for(const [i,label]of ['待执行 / 派工','待验收 / 审核','逾期待办','未结问题 / 后续'].entries())Eam.text('metric-label-'+i,label);
 function draw(){if(!data)return;const keyword=$('wb-search').value.trim(),group=$('wb-group').value,rows=data.items.filter(x=>(!group||x.group===group)&&[x.title,x.equipment,x.sourceId,x.owner].join(' ').includes(keyword));page=Math.min(page,Math.max(1,Math.ceil(rows.length/8)));$('role-queue').replaceChildren();for(const r of rows.slice((page-1)*8,page*8)){const tr=$('wb-row').content.firstElementChild.cloneNode(true),cell=name=>tr.querySelector('[data-cell="'+name+'"]');cell('source').textContent=r.source+' / '+r.sourceId;cell('title').textContent=r.equipment+' / '+r.title;cell('owner').textContent=r.owner;cell('due').textContent=r.dueAt||'未设置期限';cell('status').textContent=r.groupLabel+' · '+r.status;if(r.overdue)cell('due').className='text-danger';const b=tr.querySelector('[data-open]');b.textContent=r.action;b.onclick=()=>Eam.go(r.target,r.query);$('role-queue').append(tr);}ui.decorateTables();ui.setTableStatus('role-queue','loaded');ui.pagination($('wb-pagination'),{page,pages:Math.max(1,Math.ceil(rows.length/8)),total:rows.length,pageSize:8,onChange:p=>{page=p;draw();}});}
 async function refresh(){const token=++ticket;$('wb-refresh').disabled=true;ui.setTableStatus('role-queue','loading');try{const result=await EamWorkbenchApi.request('GET','/workbench');if(token!==ticket)return;data=result;document.querySelector('h1').textContent=Eam.role()[1]+'工作台';Eam.text('role-note','当前人员：'+Eam.person().name+'；读取时间 '+EamProduct.time(data.dataAsOf)+(data.errors.length?'；部分来源不可用：'+data.errors.map(e=>e.source+'：'+e.message).join('；'):'；来源：点检、保养、异常、维修。'));for(const [i,key]of ['pending','review','overdue','unclosed'].entries())Eam.text('metric-'+i,data.errors.length?'—':data.metrics[key]);if($('wb-group').options.length===1)for(const [value,label]of Object.entries(data.groups))$('wb-group').add(new Option(label,value));draw();}catch(e){data=null;for(let i=0;i<4;i++)Eam.text('metric-'+i,'—');Eam.text('role-note',e.message);ui.setTableStatus('role-queue','error',e.message,refresh);}finally{if(token===ticket)$('wb-refresh').disabled=false;}}
 ui.toolIcon?.($('wb-refresh'),'refresh','刷新待办');$('wb-search').oninput=()=>{page=1;draw();};$('wb-group').onchange=()=>{page=1;draw();};$('wb-refresh').onclick=refresh;
 const visible=()=>{if(!document.hidden)refresh();};document.addEventListener('visibilitychange',visible);window.addEventListener('pageshow',visible);Eam.onDispose?.(document.body,()=>{document.removeEventListener('visibilitychange',visible);window.removeEventListener('pageshow',visible);});await refresh();
});
